{ "version": 1, "title": "Value vs Reference", "page": { "width": 1008.0, "height": 612.0, "margin": 36.0, "background": "#ffffff" }, "elements": [ { "type": "label", "id": "title", "x": 48.0, "y": 34.0, "text": "Value vs Reference", "style": { "fill": null, "stroke": null, "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 30.0, "font_weight": 700, "italic": null, "text_color": null, "align": null, "padding": null } }, { "type": "label", "id": "sub", "x": 48.0, "y": 72.0, "text": "Primitives copy the value. Objects copy the reference: two names, one object.", "style": { "fill": null, "stroke": null, "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 16.0, "font_weight": null, "italic": null, "text_color": "#6b6a66", "align": null, "padding": null } }, { "type": "shape", "id": "hL", "kind": "rect", "x": 48.0, "y": 118.0, "w": 430.0, "h": 38.0, "text": "Primitives copy the VALUE", "style": { "fill": "#e3edfb", "stroke": "#2a78d6", "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 17.0, "font_weight": 700, "italic": null, "text_color": "#10386b", "align": null, "padding": null } }, { "type": "shape", "id": "codeL", "kind": "rect", "x": 48.0, "y": 168.0, "w": 430.0, "h": 100.0, "text": "let a = 10;
