rner_radius": null, "font": null, "font_size": null, "font_weight": null, "italic": null, "text_color": null, "align": null, "padding": null } }, { "type": "label", "id": "noteR", "x": 530.0, "y": 404.0, "text": "One object, two names. Arrays and functions
